# -*- coding: utf-8 -*-
"""卷面标注答案卷交付门禁（exam-word-skill §11.6）。

独立于生成器，从成品 DOCX 反查内容，避免「自己生成自己判」：

    python scripts/verify_answer_keyed_paper.py out.docx [--spec keyed-spec.json] [--json]

检查项见 CHECKS；任何一项失败即 valid=false 并列出 errors。
"""
import argparse
import json
import re
import sys
import zipfile
from pathlib import Path

from docx import Document
from lxml import etree

W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
RUBRIC_LABEL = "参考答案与评分要点："
AI_MARKS = (
    "AI生成", "由 AI 生成", "部分内容可能由 AI 生成", "由人工智能生成",
    "本试卷由 AI", "本文档由 AI", "generated by", "Generated by",
    "ChatGPT 生成", "Claude 生成", "通义千问生成", "文心一言生成",
)
FULL_MARKS = [10, 10, 10, 10, 15, 15]
BARE_LABELS = re.compile(r"^\s*(答案：|参考答案\s*$|评分要点\s*$)")
BAD_MARK = re.compile(r"（\d+分）|\(\d+\s*分\)|（\d+\s{2,}分）|\d+\s*分（")
GOOD_MARK = re.compile(r"（\d+ 分）")
SUBQ = re.compile(r"^\s*(（\d+）|[①②③④⑤⑥⑦⑧⑨⑩])")


def txt(el):
    return "".join(t.text or "" for t in el.iter(W + "t"))


def body_paragraphs(path):
    with zipfile.ZipFile(path) as z:
        root = etree.fromstring(z.read("word/document.xml"))
    body = root.find(W + "body")
    return [txt(p) for p in body.findall(W + "p")]


def docprops_text(path):
    with zipfile.ZipFile(path) as z:
        out = ""
        for name in ("docProps/core.xml", "docProps/app.xml", "docProps/custom.xml"):
            if name in z.namelist():
                out += z.read(name).decode("utf-8", "ignore")
        return out


def run(path, spec_path=None):
    errors, checks = [], {}
    doc = Document(str(path))
    paras = body_paragraphs(path)
    text = "\n".join(paras)
    props = docprops_text(path)

    def check(name, ok, detail=""):
        checks[name] = {"ok": bool(ok), "detail": "pass" if ok else detail}
        if not ok:
            errors.append(f"{name}: {detail}")

    # 1 卷头：卷别后带「答案」，学生卷卷头三件套保留
    head = "\n".join(paras[:6])
    check("answer_label", bool(re.search(r"（[AB] 卷）答案", head)),
          "卷头未见「（X 卷）答案」")
    check("student_header",
          all(k in head for k in ("序号", "学号", "姓名", "专业及班级")),
          "学号/姓名栏缺失")

    # 2 得分表：保留，分数/得分两行为空
    tbl_ok = False
    detail = "无得分表"
    if doc.tables:
        rows = [[c.text.strip() for c in r.cells] for r in doc.tables[0].rows]
        detail = str(rows)
        tbl_ok = (len(rows) == 3 and rows[0][0] == "题号"
                  and all(v == "" for v in rows[1][1:] + rows[2][1:]))
    check("score_table_blank", tbl_ok, detail)

    # 3 客观题：18 个题干空括号全部填了答案
    obj_lines = []
    section = 0
    for p in paras:
        if re.match(r"^[一二三]、", p):
            section = 1
        elif re.match(r"^[四五]、", p):
            section = 0
        if section and re.match(r"^\d+[、.]", p):
            obj_lines.append(p)
    filled = [p for p in obj_lines if re.search(r"[（(]\s*[^)）\s][^)）]*[)）]\s*$", p)]
    check("objective_answers", len(obj_lines) == 18 and len(filled) == 18,
          f"客观题 {len(obj_lines)} 题，已填答 {len(filled)} 题")

    # 4 主观题：6 个统一标签，无手改式裸标签
    labels = [p.strip() for p in paras if p.strip() == RUBRIC_LABEL]
    bare = [p.strip() for p in paras if BARE_LABELS.match(p)]
    check("rubric_labels", len(labels) == 6 and not bare,
          f"统一标签 {len(labels)} 个 / 裸标签 {bare}")

    # 5 分值格式统一 + 每题合计 = 满分
    bad = BAD_MARK.findall(text)
    groups, cur = [], None
    for p in paras:
        if p.strip() == RUBRIC_LABEL:
            cur = []
            groups.append(cur)
        elif cur is not None:
            m = GOOD_MARK.search(p)
            if m:
                cur.append(int(re.search(r"\d+", m.group()).group()))
    sums = [sum(g) for g in groups]
    check("mark_format", not bad, f"不规范分值写法 {bad[:5]}")
    check("mark_sum", sums == FULL_MARKS,
          f"各题合计 {sums}，预期 {FULL_MARKS}")

    # 6 无残留答题空白（空段且段后间距异常）
    with zipfile.ZipFile(path) as z:
        root = etree.fromstring(z.read("word/document.xml"))
    blank_big = 0
    for p in root.iter(W + "p"):
        if txt(p).strip():
            continue
        pPr = p.find(W + "pPr")
        sp = pPr.find(W + "spacing") if pPr is not None else None
        if sp is not None and int(sp.get(W + "after", "0") or 0) > 800:
            blank_big += 1
    check("no_answer_space", blank_big == 0, f"残留大段空白 {blank_big} 处")

    # 7 小问逐行缩进（425 / -142）；答案要点里的（1）不算小问
    subq_total = subq_ok = 0
    in_answer = False
    for para in doc.paragraphs:
        t = para.text.strip()
        if t == RUBRIC_LABEL:
            in_answer = True
            continue
        if in_answer and re.match(r"^\d+[.、]", t):
            in_answer = False
        if in_answer or not SUBQ.match(para.text):
            continue
        subq_total += 1
        pf = para.paragraph_format
        l = pf.left_indent.twips if pf.left_indent is not None else None
        f = pf.first_line_indent.twips if pf.first_line_indent is not None else None
        if l == 425 and f == -142:
            subq_ok += 1
    check("subquestion_indent", subq_total > 0 and subq_ok == subq_total,
          f"{subq_ok}/{subq_total} 小问缩进正确")

    # 8 无硬分页（派生 spec 合并为单页自然流动）
    page_breaks = sum(
        1 for br in root.iter(W + "br") if br.get(W + "type") == "page"
    )
    check("no_hard_page_break", page_breaks == 0, f"硬分页 {page_breaks} 处")

    # 9 AI 痕迹（正文 + docProps，含 app.xml 的 Application）
    hits = [m for m in AI_MARKS if m in text or m in props]
    check("no_ai_marks", not hits, f"命中 {hits}")

    application = ""
    with zipfile.ZipFile(path) as z:
        if "docProps/app.xml" in z.namelist():
            app = z.read("docProps/app.xml").decode("utf-8", "ignore")
            m = re.search(r"<Application>([^<]*)</Application>", app)
            application = m.group(1) if m else ""
    report = {
        "output": str(path),
        "valid": not errors,
        "errors": errors,
        "checks": checks,
        "paragraphs": len(paras),
        "rubric_points": sum(len(g) for g in groups),
        "application": application,
    }
    return report


def main():
    ap = argparse.ArgumentParser(description="Verify an answer-keyed exam paper (§11.6)")
    ap.add_argument("docx")
    ap.add_argument("--spec")
    ap.add_argument("--json", action="store_true")
    args = ap.parse_args()
    report = run(Path(args.docx), Path(args.spec) if args.spec else None)
    if args.json:
        print(json.dumps(report, ensure_ascii=False, indent=2))
    else:
        print("valid:", report["valid"])
        for name, c in report["checks"].items():
            print(f"  {'OK ' if c['ok'] else 'FAIL'} {name}: {c['detail']}")
        for e in report["errors"]:
            print("  ERROR", e)
    return 0 if report["valid"] else 1


if __name__ == "__main__":
    main()
